arguments.command:
cd /workspace && python3 - <<'EOF'
import json, subprocess
d = json.load(open('examples.json'))
fx = d[1]
inp = json.dumps(fx['input']).encode()
p = subprocess.run(['python3','-I','-B','project/solver.py'], input=inp, capture_output=True)
got = json.loads(p.stdout)
exp = fx['output']
g = got['cases'][0]; e = exp['cases'][0]
for k in e:
    if g.get(k) != e[k]:
        print('DIFF in', k)
        if k == 'state':
            for i,(a,b) in enumerate(zip(g[k],e[k])):
                if a!=b: print('  idx',i,'got',a,'exp',b)
        elif k == 'trace':
            print('  got len', len(g[k]), 'exp len', len(e[k]))
            for i,(a,b) in enumerate(zip(g[k],e[k])):
                if a!=b: print('  trace',i,'\n   got',a,'\n   exp',b)
        else:
            print('  got', g.get(k))
            print('  exp', e[k])
print('stderr:', p.stderr.decode()[:500])
EOF
